def load(index):
    """Monthly DataFrame (index = first day of month) with what was KNOWN at the end of each month."""
    ch = pd.Series({pd.Timestamp(k[:4]+'-'+k[4:6]+'-'+k[6:]): float(v) for k, v in (x.split(':') for x in TARGET_CHANGES.split())})
    daily = ch.reindex(pd.date_range('2008-01-21', '2026-12-31')).ffill()
    tgt = daily.resample('MS').last()            # value in force at the end of the month
    fund = pd.Series({pd.Timestamp(k[:4]+'-'+k[4:]+'-01'): float(v) for k, v in (x.split(':') for x in FUNDING_0607.split())})
    pol = pd.concat([fund, tgt]).groupby(level=0).last()
    ust = pd.DataFrame({pd.Timestamp('20'+k[:2]+'-'+k[2:]+'-01'): [float(a) for a in v.split('/')] for k, v in (x.split(':') for x in UST.split())}).T
    ust.columns = ['ust10', 'ust3m']
    inf = pd.Series([float(x) for x in INFL_FROM_2006_01.split()], index=pd.date_range('2006-01-01', periods=249, freq='MS'))
    out = pd.DataFrame({'policy_rate': pol, 'ust10': ust.ust10, 'ust3m': ust.ust3m, 'inflation_lag1': inf.shift(1)})
    return out.reindex(index)
